<script setup lang="ts">
import { computed,reactive,ref } from "vue";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import Toolbar from "@/components/zs/Toolbar.vue"; import ActivityTimeline from "@/components/crm/ActivityTimeline.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import ZButton from "@/components/zs/ZButton.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue"; import Pagination from "@/components/crm/Pagination.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import type {CrmActivity} from "@/types/crm"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("CRM Activities","Unified customer activity timeline.");const data=useCrmData(),type=ref("All types"),status=ref("All statuses"),page=ref(1),open=ref(false),editingId=ref<string|null>(null);const listing=useAsyncData(()=>crmRepository.activitiesPage(data.activeCompanyId.value,{type:type.value==="All types"?undefined:type.value.toUpperCase(),status:status.value==="All statuses"?undefined:status.value,page:page.value,per_page:15}),{watch:[data.activeCompanyId,type,status,page]});const items=computed(()=>listing.data.value?.data??[]);const form=reactive({type:"CALL",subject:"",description:"",related_type:"",related_id:"",owner_id:"",due_at:"",priority:"MEDIUM",status:"PENDING"});
function edit(item?:CrmActivity){editingId.value=item?.id??null;Object.assign(form,{type:item?.type.toUpperCase()??"CALL",subject:item?.subject??"",description:item?.description??"",related_type:item?.related?.type.toLowerCase()??"",related_id:item?.related?.id??"",owner_id:item?.ownerId?String(item.ownerId):"",due_at:item?.dueAt?.slice(0,16)??"",priority:item?.priority.toUpperCase()??"MEDIUM",status:item?.status??"PENDING"});open.value=true;}
const mutation=useMutation(()=>{const input={...form,related_type:form.related_type||null,related_id:form.related_id||null,owner_id:form.owner_id?Number(form.owner_id):null,due_at:form.due_at||null};return editingId.value?crmRepository.updateActivity(data.activeCompanyId.value,editingId.value,input):crmRepository.createActivity(data.activeCompanyId.value,input)});const transitionMutation=useMutation((item:CrmActivity)=>crmRepository.transitionActivity(data.activeCompanyId.value,item.id,item.status==="COMPLETED"?"PENDING":"COMPLETED"));async function save(){const saved=await mutation.run();if(!saved)return;open.value=false;await Promise.all([listing.refresh(),data.activities.refresh(),data.dashboard.refresh()]);showToast("Activity saved",saved.subject,"success");}async function transition(item:CrmActivity){const saved=await transitionMutation.run(item);if(!saved)return;await Promise.all([listing.refresh(),data.activities.refresh(),data.dashboard.refresh()]);showToast("Activity updated",saved.status,"success");}
</script>
<template><AppShell><PageHeader title="Activities" :description="`${listing.data.value?.total??0} calls, emails, notes, meetings and tasks`"><template #actions><ZButton @click="edit()">Log activity</ZButton></template></PageHeader><Panel><Toolbar><select v-model="type" class="field max-w-48"><option>All types</option><option v-for="value in ['Email','Call','Note','Task','Meeting']" :key="value">{{value}}</option></select><select v-model="status" class="field max-w-48"><option>All statuses</option><option>PENDING</option><option>COMPLETED</option><option>CANCELLED</option></select></Toolbar><AsyncSection :loading="listing.loading.value" :error="listing.error.value||transitionMutation.error.value" :empty="listing.data.value?.total===0" @retry="listing.refresh"><div class="p-4"><ActivityTimeline :items="items" actions @edit="edit" @transition="transition"/><div class="mt-4"><Pagination :page="listing.data.value?.currentPage??1" :pages="listing.data.value?.lastPage??1" :total="listing.data.value?.total??0" @change="page=$event"/></div></div></AsyncSection></Panel><SidePanel :open="open" :title="editingId?'Edit activity':'Log activity'" @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="save"><label><span class="label-caps">Type</span><select v-model="form.type" class="field mt-1.5"><option v-for="value in ['CALL','MEETING','EMAIL','TASK','NOTE']" :key="value">{{value}}</option></select></label><Field v-model="form.subject" label="Subject" required/><label><span class="label-caps">Related to</span><select v-model="form.related_type" class="field mt-1.5"><option value="">General</option><option value="account">Account</option><option value="contact">Contact</option><option value="lead">Lead</option><option value="deal">Deal</option></select></label><label><span class="label-caps">Record</span><select v-model="form.related_id" class="field mt-1.5"><option value="">Select record</option><option v-for="item in form.related_type==='account'?(data.companies.data.value??[]):form.related_type==='contact'?(data.contacts.data.value??[]):form.related_type==='lead'?(data.leads.data.value??[]):form.related_type==='deal'?(data.deals.data.value??[]):[]" :key="item.id" :value="item.id">{{item.name}}</option></select></label><Field v-model="form.due_at" label="Due at" type="datetime-local"/><label><span class="label-caps">Priority</span><select v-model="form.priority" class="field mt-1.5"><option>LOW</option><option>MEDIUM</option><option>HIGH</option></select></label><label><span class="label-caps">Owner</span><select v-model="form.owner_id" class="field mt-1.5"><option value="">Unassigned</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></label><label class="sm:col-span-2"><span class="label-caps">Description</span><textarea v-model="form.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage class="sm:col-span-2" :message="mutation.error.value?.message"/><ZButton type="submit" :disabled="mutation.saving.value">Save activity</ZButton></form></SidePanel></AppShell></template>
